import json
from datetime import datetime

# ---------- 菜單 ----------
MENU = [
    {'id': '1', 'name': '蛋餅', 'price': 35},
    {'id': '2', 'name': '漢堡', 'price': 45},
    {'id': '3', 'name': '吐司', 'price': 30},
    {'id': '4', 'name': '奶茶', 'price': 25},
    {'id': '5', 'name': '豆漿', 'price': 20},
    {'id': '6', 'name': '蘿蔔糕', 'price': 40},
    {'id': '7', 'name': '鐵板麵', 'price': 55},
    {'id': '8', 'name': '紅茶', 'price': 20},
]

STATUSES = ('pending', 'preparing', 'done')
ORDER_TYPES = ('dine_in', 'takeout')

# ---------- 訂單資料 ----------
ORDERS = []
_state = {'next_id': 1}


def _find_menu(menu_id):
    for m in MENU:
        if m['id'] == menu_id:
            return m
    return None


def _parse_body(body):
    if not body:
        return None
    try:
        return json.loads(body.decode('utf-8'))
    except Exception:
        raise ValueError('請求內容不是有效的 JSON')


def _copy_order(order):
    result = dict(order)
    result['items'] = [dict(i) for i in order['items']]
    return result


# ---------- 訂單 ----------
def create_order(body):
    try:
        data = _parse_body(body)
    except ValueError as e:
        return 400, {'error': str(e)}
    if not isinstance(data, dict):
        return 400, {'error': '請提供訂單內容'}

    order_type = data.get('order_type')
    if order_type not in ORDER_TYPES:
        return 400, {'error': '請選擇內用或外帶'}

    table = data.get('table', '')
    if table is None:
        table = ''
    if isinstance(table, bool) or not isinstance(table, (str, int)):
        return 400, {'error': '桌號格式不正確'}
    table = str(table).strip()
    if len(table) > 20:
        return 400, {'error': '桌號過長'}
    if order_type == 'dine_in' and table == '':
        return 400, {'error': '內用請填寫桌號'}
    if order_type == 'takeout':
        table = ''

    raw_items = data.get('items')
    if not isinstance(raw_items, list) or len(raw_items) == 0:
        return 400, {'error': '請至少選擇一項餐點'}

    merged = {}
    for raw in raw_items:
        if not isinstance(raw, dict):
            return 400, {'error': '餐點格式不正確'}
        mid = raw.get('menu_item_id')
        if isinstance(mid, bool) or not isinstance(mid, (str, int)):
            return 400, {'error': '餐點編號不正確'}
        mid = str(mid)
        menu_item = _find_menu(mid)
        if menu_item is None:
            return 400, {'error': '找不到餐點：' + mid}
        qty = raw.get('quantity')
        if isinstance(qty, bool) or not isinstance(qty, int):
            return 400, {'error': '數量必須是整數'}
        if qty < 1:
            return 400, {'error': '數量必須至少為 1'}
        merged[mid] = merged.get(mid, 0) + qty
        if merged[mid] > 99:
            return 400, {'error': '單一餐點數量不可超過 99'}

    items = []
    total = 0
    for mid, qty in merged.items():
        m = _find_menu(mid)
        items.append({
            'menu_item_id': mid,
            'name': m['name'],
            'price': m['price'],
            'quantity': qty,
        })
        total += m['price'] * qty

    order = {
        'id': str(_state['next_id']),
        'order_type': order_type,
        'table': table,
        'status': 'pending',
        'total': total,
        'created_at': datetime.now().isoformat(timespec='seconds'),
        'items': items,
    }
    _state['next_id'] += 1
    ORDERS.append(order)
    return 201, _copy_order(order)


def list_orders(body):
    status = None
    try:
        data = _parse_body(body)
        if isinstance(data, dict):
            status = data.get('status')
    except ValueError:
        pass
    if status is not None and status not in STATUSES:
        return 400, {'error': '狀態必須是 pending、preparing 或 done'}
    result = []
    for o in ORDERS:
        if status is None or o['status'] == status:
            result.append(_copy_order(o))
    result.sort(key=lambda o: (o['created_at'], int(o['id'])))
    return 200, {'items': result}


def update_order(order_id, body):
    try:
        data = _parse_body(body)
    except ValueError as e:
        return 400, {'error': str(e)}
    if not isinstance(data, dict):
        return 400, {'error': '請提供要更新的狀態'}
    status = data.get('status')
    if status not in STATUSES:
        return 400, {'error': '狀態必須是 pending、preparing 或 done'}
    for o in ORDERS:
        if o['id'] == order_id:
            o['status'] = status
            return 200, _copy_order(o)
    return 404, {'error': '找不到這張訂單'}


# ---------- 營業額統計 ----------
def stats_today():
    today = datetime.now().date().isoformat()
    count = 0
    amount = 0
    qty_by_item = {}
    for o in ORDERS:
        if not o['created_at'].startswith(today):
            continue
        count += 1
        amount += o['total']
        for it in o['items']:
            key = it['menu_item_id']
            if key not in qty_by_item:
                qty_by_item[key] = {'menu_item_id': key, 'name': it['name'], 'quantity': 0}
            qty_by_item[key]['quantity'] += it['quantity']
    ranked = sorted(qty_by_item.values(), key=lambda x: (-x['quantity'], int(x['menu_item_id'])))
    return 200, {'order_count': count, 'total_amount': amount, 'top_items': ranked[:3]}


# ---------- 路由與回應 ----------
def _route(method, path, body):
    path = '/' + (path or '').strip('/')

    if method == 'OPTIONS':
        return 200, {}

    if path == '/menu':
        if method != 'GET':
            return 405, {'error': '不支援此方法'}
        return 200, {'items': [dict(m) for m in MENU]}

    if path == '/orders':
        if method == 'GET':
            return list_orders(body)
        if method == 'POST':
            return create_order(body)
        return 405, {'error': '不支援此方法'}

    if path.startswith('/orders/'):
        order_id = path[len('/orders/'):]
        if method == 'PATCH':
            return update_order(order_id, body)
        return 405, {'error': '不支援此方法'}

    if path == '/stats/today':
        if method != 'GET':
            return 405, {'error': '不支援此方法'}
        return stats_today()

    return 404, {'error': '找不到此路徑'}


def handle(method: str, path: str, body: bytes) -> tuple[int, dict]:
    try:
        return _route((method or '').upper(), path, body)
    except Exception:
        return 500, {'error': '伺服器發生錯誤'}

