(function () {
  'use strict';

  var STATUS_LABEL = { pending: '待做', preparing: '製作中', done: '完成' };
  var STATUS_ORDER = ['pending', 'preparing', 'done'];
  var TYPE_LABEL = { dine_in: '內用', takeout: '外帶' };

  var menu = [];
  var cart = {};
  var orders = [];
  var currentTab = 'order';
  var currentFilter = 'all';
  var messageTimer = null;

  function $(id) { return document.getElementById(id); }

  function el(tag, className, text) {
    var node = document.createElement(tag);
    if (className) node.className = className;
    if (text !== undefined && text !== null) node.textContent = text;
    return node;
  }

  function clear(node) {
    while (node.firstChild) node.removeChild(node.firstChild);
  }

  /* ---------- API 呼叫 ---------- */
  function api(path, method, payload) {
    var options = { method: method || 'GET', headers: {} };
    if (payload !== undefined) {
      options.headers['Content-Type'] = 'application/json';
      options.body = JSON.stringify(payload);
    }
    return fetch('api/' + path, options).then(function (res) {
      return res.json().catch(function () { return {}; }).then(function (data) {
        if (!res.ok) {
          throw new Error(data.error || '請求失敗，請稍後再試');
        }
        return data;
      });
    });
  }

  function showMessage(text, isError) {
    var box = $('message');
    box.textContent = text;
    box.className = 'message ' + (isError ? 'error' : 'success');
    if (messageTimer) clearTimeout(messageTimer);
    messageTimer = setTimeout(function () {
      box.className = 'message hidden';
    }, 5000);
  }

  function errorText(err) {
    if (err && err.message === 'Failed to fetch') return '無法連線到伺服器';
    return (err && err.message) || '發生未知錯誤';
  }

  /* ---------- 分頁導覽 ---------- */
  function showTab(name) {
    currentTab = name;
    var buttons = document.querySelectorAll('.tab-btn');
    for (var i = 0; i < buttons.length; i++) {
      buttons[i].classList.toggle('active', buttons[i].getAttribute('data-tab') === name);
    }
    ['order', 'kitchen', 'stats'].forEach(function (t) {
      $('tab-' + t).classList.toggle('hidden', t !== name);
    });
    if (name === 'order') loadMenu();
    if (name === 'kitchen') loadOrders();
    if (name === 'stats') loadStats();
  }

  /* ---------- 點餐 ---------- */
  function cartTotal() {
    var total = 0;
    menu.forEach(function (item) {
      total += item.price * (cart[item.id] || 0);
    });
    return total;
  }

  function renderTotal() {
    $('cart-total').textContent = cartTotal() + ' 元';
  }

  function changeQty(id, delta) {
    var next = (cart[id] || 0) + delta;
    if (next < 0) next = 0;
    if (next > 99) next = 99;
    cart[id] = next;
    renderMenu();
  }

  function renderMenu() {
    var list = $('menu-list');
    clear(list);
    menu.forEach(function (item) {
      var li = el('li', 'menu-item');
      var info = el('div', 'menu-info');
      info.appendChild(el('span', 'menu-name', item.name));
      info.appendChild(el('span', 'menu-price', item.price + ' 元'));
      var qtyBox = el('div', 'qty');
      var minus = el('button', 'qty-btn', '−');
      minus.type = 'button';
      minus.setAttribute('aria-label', '減少 ' + item.name);
      minus.addEventListener('click', function () { changeQty(item.id, -1); });
      var count = el('span', 'qty-count', String(cart[item.id] || 0));
      var plus = el('button', 'qty-btn', '+');
      plus.type = 'button';
      plus.setAttribute('aria-label', '增加 ' + item.name);
      plus.addEventListener('click', function () { changeQty(item.id, 1); });
      qtyBox.appendChild(minus);
      qtyBox.appendChild(count);
      qtyBox.appendChild(plus);
      li.appendChild(info);
      li.appendChild(qtyBox);
      list.appendChild(li);
    });
    renderTotal();
  }

  function loadMenu() {
    return api('menu').then(function (data) {
      menu = data.items || [];
      renderMenu();
    }).catch(function (err) {
      showMessage('載入菜單失敗：' + errorText(err), true);
    });
  }

  function selectedType() {
    var radios = document.getElementsByName('order-type');
    for (var i = 0; i < radios.length; i++) {
      if (radios[i].checked) return radios[i].value;
    }
    return 'dine_in';
  }

  function updateTableRow() {
    $('table-row').classList.toggle('hidden', selectedType() !== 'dine_in');
  }

  function submitOrder() {
    var type = selectedType();
    var table = $('table-input').value.trim();
    var items = [];
    menu.forEach(function (item) {
      var q = cart[item.id] || 0;
      if (q > 0) items.push({ menu_item_id: item.id, quantity: q });
    });
    if (items.length === 0) {
      showMessage('請至少選擇一項餐點', true);
      return;
    }
    if (type === 'dine_in' && table === '') {
      showMessage('內用請填寫桌號', true);
      return;
    }
    var btn = $('submit-order');
    btn.disabled = true;
    api('orders', 'POST', {
      order_type: type,
      table: type === 'dine_in' ? table : '',
      items: items
    }).then(function (order) {
      cart = {};
      $('table-input').value = '';
      renderMenu();
      showMessage('訂單已送出！編號 #' + order.id + '，合計 ' + order.total + ' 元', false);
    }).catch(function (err) {
      showMessage('送出失敗：' + errorText(err), true);
    }).then(function () {
      btn.disabled = false;
    });
  }

  /* ---------- 廚房 ---------- */
  function timeText(iso) {
    if (!iso || iso.length < 16) return '';
    return iso.slice(11, 16);
  }

  function renderOrders() {
    var box = $('order-list');
    clear(box);
    var shown = orders.filter(function (o) {
      return currentFilter === 'all' || o.status === currentFilter;
    });
    if (shown.length === 0) {
      box.appendChild(el('p', 'empty', '目前沒有訂單'));
      return;
    }
    shown.forEach(function (o) {
      var card = el('div', 'order-card status-' + o.status);
      var head = el('div', 'order-head');
      var title = '#' + o.id + '　' + (TYPE_LABEL[o.order_type] || o.order_type);
      if (o.order_type === 'dine_in' && o.table) title += '　桌號 ' + o.table;
      head.appendChild(el('strong', null, title));
      head.appendChild(el('span', 'badge', STATUS_LABEL[o.status] || o.status));
      card.appendChild(head);
      card.appendChild(el('div', 'order-time', '時間 ' + timeText(o.created_at)));
      var ul = el('ul', 'order-items');
      (o.items || []).forEach(function (it) {
        ul.appendChild(el('li', null, it.name + ' × ' + it.quantity));
      });
      card.appendChild(ul);
      card.appendChild(el('div', 'order-total', '合計 ' + o.total + ' 元'));
      var actions = el('div', 'order-actions');
      STATUS_ORDER.forEach(function (s) {
        var b = el('button', 'status-btn st-' + s, STATUS_LABEL[s]);
        b.type = 'button';
        if (o.status === s) {
          b.disabled = true;
          b.classList.add('current');
        }
        b.addEventListener('click', function () { setStatus(o.id, s); });
        actions.appendChild(b);
      });
      card.appendChild(actions);
      box.appendChild(card);
    });
  }

  function loadOrders(silent) {
    return api('orders').then(function (data) {
      orders = data.items || [];
      renderOrders();
    }).catch(function (err) {
      if (!silent) showMessage('載入訂單失敗：' + errorText(err), true);
    });
  }

  function setStatus(id, status) {
    api('orders/' + encodeURIComponent(id), 'PATCH', { status: status }).then(function () {
      return loadOrders();
    }).catch(function (err) {
      showMessage('更新狀態失敗：' + errorText(err), true);
    });
  }

  function setFilter(name) {
    currentFilter = name;
    var buttons = document.querySelectorAll('.filter-btn[data-filter]');
    for (var i = 0; i < buttons.length; i++) {
      buttons[i].classList.toggle('active', buttons[i].getAttribute('data-filter') === name);
    }
    renderOrders();
  }

  /* ---------- 營業額 ---------- */
  function loadStats() {
    return api('stats/today').then(function (data) {
      $('stat-count').textContent = String(data.order_count || 0);
      $('stat-amount').textContent = (data.total_amount || 0) + ' 元';
      var list = $('top-list');
      clear(list);
      var tops = data.top_items || [];
      if (tops.length === 0) {
        list.appendChild(el('li', 'empty', '今天還沒有銷售紀錄'));
      }
      tops.forEach(function (t) {
        list.appendChild(el('li', null, t.name + '：' + t.quantity + ' 份'));
      });
    }).catch(function (err) {
      showMessage('載入營業額失敗：' + errorText(err), true);
    });
  }

  /* ---------- 初始化 ---------- */
  function init() {
    var tabButtons = document.querySelectorAll('.tab-btn');
    Array.prototype.forEach.call(tabButtons, function (b) {
      b.addEventListener('click', function () { showTab(b.getAttribute('data-tab')); });
    });
    var filterButtons = document.querySelectorAll('.filter-btn[data-filter]');
    Array.prototype.forEach.call(filterButtons, function (b) {
      b.addEventListener('click', function () { setFilter(b.getAttribute('data-filter')); });
    });
    var radios = document.getElementsByName('order-type');
    Array.prototype.forEach.call(radios, function (r) {
      r.addEventListener('change', updateTableRow);
    });
    $('submit-order').addEventListener('click', submitOrder);
    $('refresh-orders').addEventListener('click', function () { loadOrders(); });
    $('refresh-stats').addEventListener('click', function () { loadStats(); });
    updateTableRow();
    showTab('order');
    setInterval(function () {
      if (currentTab === 'kitchen') loadOrders(true);
    }, 5000);
  }

  document.addEventListener('DOMContentLoaded', init);
})();

